import { createRoot } from 'react-dom/client';
import { Toaster } from 'sonner';
import App from './App';
import './styles.css';

const root = createRoot(document.getElementById('root')!);
root.render(
  <>
    <App />
    <Toaster richColors position="top-right" />
  </>
);

/* ---------- DESIGN TOKENS ---------- */
/* design_mode: premium_modern (Premium Modern (Linear/Vercel-style)) */
:root {
  --background: 240 6% 6%;
  --foreground: 0 0% 96%;
  --muted: 240 4% 13%;
  --muted-foreground: 240 5% 65%;
  --card: 240 6% 9%;
  --border: 240 4% 18%;
  --primary: 243 75% 65%;
  --primary-foreground: 0 0% 100%;
  --accent: 189 94% 55%;
  --accent-foreground: 240 6% 6%;
  --radius: 0.75rem;
  --font-display: Inter, system-ui, sans-serif;
  --font-body: Inter, system-ui, sans-serif;
  --font-mono: JetBrains Mono, ui-monospace, monospace;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.06), 0 1px 1px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 24px 48px -12px rgba(0,0,0,0.18), 0 8px 16px -8px rgba(0,0,0,0.10);
  --shadow-glow: 0 0 32px -8px hsl(var(--primary) / 0.45);
  --gradient-primary: linear-gradient(135deg, hsl(243 75% 65%), hsl(189 94% 55%));
}

html { scroll-behavior: smooth; }
body {
  font-family: var(--font-body);
  background: hsl(var(--background));
  color: hsl(var(--foreground));
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
h1, h2, h3, h4 { font-family: var(--font-display); letter-spacing: -0.02em; }
code, pre { font-family: var(--font-mono); }

/* ---------- PREMIUM UTILITY CLASSES ---------- */
.gradient-text {
  background-image: var(--gradient-primary);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.gradient-bg { background-image: var(--gradient-primary); }
.glass {
  background: hsl(var(--card) / 0.6);
  backdrop-filter: blur(16px) saturate(180%);
  -webkit-backdrop-filter: blur(16px) saturate(180%);
  border: 1px solid hsl(var(--border) / 0.5);
}
.shadow-soft  { box-shadow: var(--shadow-md); }
.shadow-lifted{ box-shadow: var(--shadow-lg); }
.glow         { box-shadow: var(--shadow-glow); }
.hover-lift { transition: transform 200ms ease, box-shadow 200ms ease; }
.hover-lift:hover { transform: translateY(-2px); box-shadow: var(--shadow-lg); }
.surface-1 { background: hsl(var(--card)); border: 1px solid hsl(var(--border)); }
.surface-2 { background: hsl(var(--muted)); border: 1px solid hsl(var(--border)); }
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-track { background: hsl(var(--background)); }
::-webkit-scrollbar-thumb { background: hsl(var(--border)); border-radius: 999px; border: 2px solid hsl(var(--background)); }
*:focus-visible { outline: 2px solid hsl(var(--primary) / 0.6); outline-offset: 2px; border-radius: var(--radius); }
@keyframes fade-up { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
.animate-fade-up   { animation: fade-up 500ms ease both; }
.animate-fade-up-1 { animation: fade-up 500ms 80ms ease both; }
.animate-fade-up-2 { animation: fade-up 500ms 160ms ease both; }
.animate-fade-up-3 { animation: fade-up 500ms 240ms ease both; }

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { useState } from 'react';
import {
  Sparkles, Zap, Check, ArrowRight, ArrowLeft, ArrowUpRight,
  ChevronRight, ChevronDown, ChevronUp, Menu, X, Plus, Minus,
  Star, Heart, Shield, ShieldCheck, Mail, Send, MessageSquare,
  Phone, Calendar, Clock, MapPin, Globe, Home as HomeIcon,
  User, Users, Lock, Unlock, Search, Settings, Bell,
  Code, Code2, Terminal, Cpu, Database, Cloud, Github,
  ShoppingCart, ShoppingBag, CreditCard, DollarSign, Tag,
  BarChart3, LineChart, PieChart, TrendingUp, Activity, Eye,
  Rocket, Target, Award, Trophy, Flame, Gauge,
  Sun, Moon, Palette, Layers, LayoutGrid, Layout,
  Brain, Lightbulb, Coffee, Book, BookOpen, Briefcase,
  Quote, Filter, Download, Upload, Share2, ExternalLink,
  Camera, Image as ImageIcon, Video, Music, Play, Pause,
} from 'lucide-react';
import { toast } from 'sonner';
import { cn } from './lib/utils';

const ICON_MAP: Record<string, any> = {
  Sparkles, Zap, Check, ArrowRight, ArrowLeft, ArrowUpRight,
  ChevronRight, ChevronDown, ChevronUp, Menu, X, Plus, Minus,
  Star, Heart, Shield, ShieldCheck, Mail, Send, MessageSquare,
  Phone, Calendar, Clock, MapPin, Globe, Home: HomeIcon,
  User, Users, Lock, Unlock, Search, Settings, Bell,
  Code, Code2, Terminal, Cpu, Database, Cloud, Github,
  ShoppingCart, ShoppingBag, CreditCard, DollarSign, Tag,
  BarChart3, LineChart, PieChart, TrendingUp, Activity, Eye,
  Rocket, Target, Award, Trophy, Flame, Gauge,
  Sun, Moon, Palette, Layers, LayoutGrid, Layout,
  Brain, Lightbulb, Coffee, Book, BookOpen, Briefcase,
  Quote, Filter, Download, Upload, Share2, ExternalLink,
  Camera, Image: ImageIcon, Video, Music, Play, Pause,
};

const BRAND: string = "Forest Cafe";
const TAGLINE: string = "Warmth in every cup";
const HEADLINE: string = "Cozy Coffee";
const SUBHEAD: string = "Experience the perfect blend of comfort and flavor";
const PRIMARY_CTA: string = "Explore Our Menu";
const SECONDARY_CTA: string | null = "Learn About Us";
const NAV: { label: string; route: string }[] = [{"label": "Home", "route": "/"}, {"label": "Menu", "route": "/menu"}, {"label": "About", "route": "/about"}, {"label": "Contact", "route": "/contact"}];
const FEATURES: { title: string; description: string; icon: string }[] = [{"title": "Handcrafted Drinks", "description": "Expertly brewed coffee and tea", "icon": "Coffee"}, {"title": "Artisanal Pastries", "description": "Freshly baked goods to pair with your drink", "icon": "Cake"}, {"title": "Cozy Atmosphere", "description": "Comfortable seating and warm decor", "icon": "Home"}, {"title": "Seasonal Menu", "description": "Fresh ingredients and rotating menu items", "icon": "Leaf"}, {"title": "Expert Baristas", "description": "Trained professionals dedicated to your coffee experience", "icon": "User"}, {"title": "Sustainable Practices", "description": "Eco-friendly operations and sourcing", "icon": "Leaf"}];
const TESTIMONIALS: { quote: string; author: string; role: string; company: string }[] = [{"quote": "Forest Cafe is my go-to spot for a delicious cup of coffee and a warm atmosphere.", "author": "Ava Morales", "role": "Marketing Manager", "company": "Greenhouse Agency"}, {"quote": "I love the seasonal menu and the expertly crafted drinks. The baristas are always friendly and knowledgeable.", "author": "Ethan Kim", "role": "Software Engineer", "company": "TechCorp"}, {"quote": "The cozy atmosphere and comfortable seating make Forest Cafe the perfect spot to work or meet with friends.", "author": "Lily Chen", "role": "Freelance Writer", "company": "Self-Employed"}, {"quote": "I appreciate the cafe's commitment to sustainable practices and sourcing high-quality ingredients.", "author": "Julian Sanchez", "role": "Environmental Consultant", "company": "EcoConsulting"}];
const PRICING: { name: string; price: string; period: string; description: string; features: string[]; cta_label: string; highlighted: boolean }[] = [{"name": "Daily Cup", "price": "3.5", "period": "per drink", "description": "Our standard coffee and tea menu", "features": ["Up to 2 drinks per day", "Access to our cozy atmosphere", "Free refills on drip coffee", "10% discount on pastries", "Complimentary Wi-Fi"], "cta_label": "Order Now", "highlighted": false}, {"name": "Monthly Subscription", "price": "20.0", "period": "per month", "description": "Unlimited drinks and perks", "features": ["Up to 30 drinks per month", "Access to exclusive promotions", "Free drinks on your birthday", "15% discount on pastries", "Complimentary pastry with every drink purchase", "Priority seating"], "cta_label": "Subscribe", "highlighted": true}, {"name": "VIP Membership", "price": "50.0", "period": "per month", "description": "Premium perks and benefits", "features": ["Up to 60 drinks per month", "Access to exclusive events", "Free drinks on your birthday and anniversary", "20% discount on pastries", "Complimentary pastry with every drink purchase", "Priority seating", "Personalized service"], "cta_label": "Join VIP", "highlighted": false}];
const FAQS: { question: string; answer: string }[] = [{"question": "What types of coffee do you offer?", "answer": "We offer a variety of coffee drinks, including espresso, cappuccino, latte, and drip coffee."}, {"question": "Do you have any non-dairy milk options?", "answer": "Yes, we offer almond milk, soy milk, and oat milk alternatives."}, {"question": "Can I make a reservation or book a table?", "answer": "Yes, you can make a reservation by calling us or booking online through our website."}, {"question": "Do you offer any discounts or promotions?", "answer": "Yes, we offer discounts for students, seniors, and military personnel, as well as seasonal promotions and loyalty rewards."}, {"question": "Can I purchase gift cards?", "answer": "Yes, you can purchase gift cards in-store or online, which can be used towards any drink or pastry purchase."}, {"question": "Do you have any gluten-free or vegan options?", "answer": "Yes, we offer a variety of gluten-free and vegan pastries and snacks, which are clearly labeled on our menu."}];
const FOOTER_LINKS: Record<string, { label: string; route: string }[]> = {"Product": [{"label": "Menu", "route": "/menu"}, {"label": "Pricing", "route": "/menu#pricing"}], "Company": [{"label": "About", "route": "/about"}, {"label": "Contact", "route": "/contact"}], "Resources": [{"label": "FAQs", "route": "/about#faqs"}, {"label": "Terms of Service", "route": "/terms"}, {"label": "Privacy Policy", "route": "/privacy"}]};
const SECTIONS_ENABLED: Record<string, boolean> = {"hero": true, "features-grid": true, "testimonials": true, "pricing-table": true, "faq": true, "cta-band": true};

function Icon({ name, className }: { name: string; className?: string }) {
  const Cmp = ICON_MAP[name] || Sparkles;
  return <Cmp className={className} aria-hidden />;
}

function scrollToId(id: string) {
  document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
}

function handleNav(item: { label: string; route: string }, onClose?: () => void) {
  return (e: React.MouseEvent) => {
    if (item.route.startsWith('#')) {
      e.preventDefault();
      scrollToId(item.route.slice(1));
    }
    onClose?.();
  };
}

function Header() {
  const [open, setOpen] = useState(false);
  return (
    <header className="sticky top-0 z-50 border-b border-border bg-background/80 backdrop-blur-md">
      <div className="container mx-auto flex max-w-6xl items-center justify-between px-6 py-4">
        <a
          href="#top"
          onClick={(e) => { e.preventDefault(); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
          className="font-display text-lg font-bold tracking-tight"
        >
          {BRAND}
        </a>
        <nav className="hidden gap-6 md:flex">
          {NAV.map((n) => (
            <a key={n.route} href={n.route} onClick={handleNav(n)} className="text-sm text-muted-foreground hover:text-foreground transition-colors">
              {n.label}
            </a>
          ))}
        </nav>
        <div className="flex items-center gap-2">
          <button
            onClick={() => toast.success('Welcome to ' + BRAND)}
            className="hidden md:inline-flex rounded-[var(--radius)] bg-primary px-4 py-2 text-sm font-medium text-primary-foreground transition-opacity hover:opacity-90"
          >
            {PRIMARY_CTA}
          </button>
          <button
            onClick={() => setOpen((v) => !v)}
            className="rounded-md border border-border p-2 md:hidden"
            aria-label="Toggle menu"
          >
            <Icon name={open ? 'X' : 'Menu'} className="h-5 w-5" />
          </button>
        </div>
      </div>
      {open && (
        <div className="border-t border-border md:hidden">
          <nav className="container mx-auto flex max-w-6xl flex-col gap-3 px-6 py-4">
            {NAV.map((n) => (
              <a
                key={n.route}
                href={n.route}
                onClick={handleNav(n, () => setOpen(false))}
                className="text-sm text-muted-foreground hover:text-foreground transition-colors"
              >
                {n.label}
              </a>
            ))}
            <button
              onClick={() => { setOpen(false); toast.success('Welcome to ' + BRAND); }}
              className="mt-2 rounded-[var(--radius)] bg-primary px-4 py-2 text-sm font-medium text-primary-foreground"
            >
              {PRIMARY_CTA}
            </button>
          </nav>
        </div>
      )}
    </header>
  );
}

function Hero() {
  return (
    <section id="hero" className="container mx-auto max-w-6xl px-6 py-24 text-center md:py-32">
      {TAGLINE && <p className="mb-4 text-sm font-medium uppercase tracking-widest text-muted-foreground">{TAGLINE}</p>}
      <h1 className="mx-auto max-w-3xl font-display text-4xl font-bold leading-tight tracking-tight md:text-6xl">
        {HEADLINE}
      </h1>
      <p className="mx-auto mt-6 max-w-2xl text-lg text-muted-foreground">
        {SUBHEAD}
      </p>
      <div className="mt-10 flex flex-wrap items-center justify-center gap-3">
        <button
          onClick={() => {
            const id = FEATURES.length ? 'features' : (PRICING.length ? 'pricing' : 'cta');
            scrollToId(id);
          }}
          className="inline-flex items-center gap-2 rounded-[var(--radius)] bg-primary px-6 py-3 text-base font-medium text-primary-foreground transition-opacity hover:opacity-90"
        >
          {PRIMARY_CTA}
          <Icon name="ArrowRight" className="h-4 w-4" />
        </button>
        {SECONDARY_CTA && (
          <button
            onClick={() => scrollToId('faq')}
            className="inline-flex items-center gap-2 rounded-[var(--radius)] border border-border px-6 py-3 text-base font-medium transition-colors hover:bg-muted"
          >
            {SECONDARY_CTA}
          </button>
        )}
      </div>
    </section>
  );
}

function FeatureGrid() {
  if (FEATURES.length === 0) return null;
  return (
    <section id="features" className="container mx-auto max-w-6xl px-6 py-20">
      <div className="mx-auto mb-12 max-w-2xl text-center">
        <h2 className="font-display text-3xl font-bold tracking-tight md:text-4xl">Features</h2>
        <p className="mt-3 text-muted-foreground">Built for {BRAND}.</p>
      </div>
      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {FEATURES.map((f, i) => (
          <div key={i} className="rounded-[var(--radius)] border border-border bg-card p-6 transition-colors hover:border-primary">
            <div className="mb-4 inline-flex h-10 w-10 items-center justify-center rounded-[var(--radius)] bg-primary/10 text-primary">
              <Icon name={f.icon} className="h-5 w-5" />
            </div>
            <h3 className="mb-2 font-display text-lg font-semibold">{f.title}</h3>
            <p className="text-sm text-muted-foreground">{f.description}</p>
          </div>
        ))}
      </div>
    </section>
  );
}

function Testimonials() {
  if (TESTIMONIALS.length === 0) return null;
  return (
    <section id="testimonials" className="border-y border-border bg-muted/30 py-20">
      <div className="container mx-auto max-w-6xl px-6">
        <h2 className="mb-12 text-center font-display text-3xl font-bold tracking-tight md:text-4xl">
          Loved by teams everywhere
        </h2>
        <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
          {TESTIMONIALS.map((t, i) => (
            <figure key={i} className="rounded-[var(--radius)] border border-border bg-card p-6">
              <Icon name="Quote" className="mb-4 h-5 w-5 text-muted-foreground" />
              <blockquote className="text-sm leading-relaxed">&ldquo;{t.quote}&rdquo;</blockquote>
              <figcaption className="mt-4 border-t border-border pt-4">
                <div className="font-semibold">{t.author}</div>
                <div className="text-xs text-muted-foreground">{t.role} · {t.company}</div>
              </figcaption>
            </figure>
          ))}
        </div>
      </div>
    </section>
  );
}

function Pricing() {
  if (PRICING.length === 0) return null;
  return (
    <section id="pricing" className="container mx-auto max-w-6xl px-6 py-20">
      <div className="mx-auto mb-12 max-w-2xl text-center">
        <h2 className="font-display text-3xl font-bold tracking-tight md:text-4xl">Simple pricing</h2>
        <p className="mt-3 text-muted-foreground">Choose the plan that fits.</p>
      </div>
      <div className="grid gap-6 md:grid-cols-3">
        {PRICING.map((p, i) => (
          <div
            key={i}
            className={cn(
              'rounded-[var(--radius)] border bg-card p-8',
              p.highlighted ? 'border-primary shadow-lg ring-1 ring-primary' : 'border-border'
            )}
          >
            {p.highlighted && (
              <div className="mb-4 inline-flex rounded-full bg-primary px-3 py-1 text-xs font-medium text-primary-foreground">
                Most popular
              </div>
            )}
            <h3 className="font-display text-xl font-semibold">{p.name}</h3>
            <p className="mt-1 text-sm text-muted-foreground">{p.description}</p>
            <div className="mt-6 flex items-baseline gap-1">
              <span className="font-display text-4xl font-bold">{p.price}</span>
              {p.period && <span className="text-sm text-muted-foreground">{p.period}</span>}
            </div>
            <button
              onClick={() => toast.success('Selected ' + p.name)}
              className={cn(
                'mt-6 w-full rounded-[var(--radius)] px-4 py-3 text-sm font-medium transition-opacity',
                p.highlighted
                  ? 'bg-primary text-primary-foreground hover:opacity-90'
                  : 'border border-border hover:bg-muted'
              )}
            >
              {p.cta_label}
            </button>
            <ul className="mt-8 space-y-3">
              {p.features.map((feat, j) => (
                <li key={j} className="flex items-start gap-2 text-sm">
                  <Icon name="Check" className="mt-0.5 h-4 w-4 flex-shrink-0 text-primary" />
                  <span>{feat}</span>
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>
    </section>
  );
}

function Faq() {
  const [openIdx, setOpenIdx] = useState<number | null>(null);
  if (FAQS.length === 0) return null;
  return (
    <section id="faq" className="container mx-auto max-w-3xl px-6 py-20">
      <h2 className="mb-12 text-center font-display text-3xl font-bold tracking-tight md:text-4xl">
        Frequently asked questions
      </h2>
      <div className="space-y-3">
        {FAQS.map((f, i) => (
          <div key={i} className="rounded-[var(--radius)] border border-border bg-card">
            <button
              onClick={() => setOpenIdx((cur) => (cur === i ? null : i))}
              className="flex w-full items-center justify-between gap-4 px-5 py-4 text-left text-sm font-medium hover:bg-muted/40"
            >
              <span>{f.question}</span>
              <Icon name={openIdx === i ? 'Minus' : 'Plus'} className="h-4 w-4 flex-shrink-0 text-muted-foreground" />
            </button>
            {openIdx === i && (
              <div className="border-t border-border px-5 py-4 text-sm text-muted-foreground">
                {f.answer}
              </div>
            )}
          </div>
        ))}
      </div>
    </section>
  );
}

function CtaBand() {
  return (
    <section id="cta" className="container mx-auto max-w-4xl px-6 py-20">
      <div className="rounded-[var(--radius)] border border-border bg-card p-12 text-center">
        <h2 className="mx-auto max-w-xl font-display text-3xl font-bold tracking-tight md:text-4xl">
          Ready when you are
        </h2>
        <p className="mx-auto mt-3 max-w-md text-muted-foreground">
          {SUBHEAD}
        </p>
        <button
          onClick={() => toast.success('Welcome to ' + BRAND)}
          className="mt-8 inline-flex items-center gap-2 rounded-[var(--radius)] bg-primary px-6 py-3 text-base font-medium text-primary-foreground transition-opacity hover:opacity-90"
        >
          {PRIMARY_CTA}
          <Icon name="ArrowRight" className="h-4 w-4" />
        </button>
      </div>
    </section>
  );
}

function Footer() {
  const cols = Object.keys(FOOTER_LINKS);
  return (
    <footer className="border-t border-border bg-muted/20">
      <div className="container mx-auto max-w-6xl px-6 py-12">
        <div className="grid gap-8 md:grid-cols-4">
          <div>
            <div className="font-display text-lg font-bold">{BRAND}</div>
            {TAGLINE && <p className="mt-2 max-w-xs text-sm text-muted-foreground">{TAGLINE}</p>}
          </div>
          {cols.map((col) => (
            <div key={col}>
              <div className="mb-3 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                {col}
              </div>
              <ul className="space-y-2">
                {FOOTER_LINKS[col].map((item) => (
                  <li key={item.route}>
                    <a
                      href={item.route}
                      onClick={handleNav(item)}
                      className="text-sm text-muted-foreground hover:text-foreground"
                    >
                      {item.label}
                    </a>
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
        <div className="mt-12 border-t border-border pt-6 text-xs text-muted-foreground">
          © {new Date().getFullYear()} {BRAND}. All rights reserved.
        </div>
      </div>
    </footer>
  );
}

export default function App() {
  return (
    <div id="top" className="min-h-screen bg-background font-body text-foreground antialiased">
      <Header />
      <main>
        {SECTIONS_ENABLED['hero'] && <Hero />}
        {SECTIONS_ENABLED['features-grid'] && <FeatureGrid />}
        {SECTIONS_ENABLED['testimonials'] && <Testimonials />}
        {SECTIONS_ENABLED['pricing-table'] && <Pricing />}
        {SECTIONS_ENABLED['faq'] && <Faq />}
        {SECTIONS_ENABLED['cta-band'] && <CtaBand />}
      </main>
      <Footer />
    </div>
  );
}
